sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float tilesX;
uniform float tilesY;
uniform float mirror;
uniform float rowOffset;
uniform float gap;
uniform float tileScale;
uniform float scroll;
uniform float scrollAngle;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float4 texT(float2 p) {
    return float4(image.eval(p));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 n = float2(max(floor(tilesX + 0.5), 1.0), max(floor(tilesY + 0.5), 1.0));
    float2 uv = coord / size * n;
    float2 sc = float2(cos(radians(scrollAngle)), sin(radians(scrollAngle))) * time * scroll;
    uv += sc;
    uv.x += floor(uv.y) * rowOffset;
    float2 cell = floor(uv);
    float2 f = fract(uv);
    if ((mirror > 0.5 && mirror < 1.5) || mirror > 2.5) f.x = mod(cell.x, 2.0) > 0.5 ? 1.0 - f.x : f.x;
    if (mirror > 1.5) f.y = mod(cell.y, 2.0) > 0.5 ? 1.0 - f.y : f.y;
    float2 gapF = gap / (size / n);
    float2 g = (f - 0.5) / max(float2(1.0) - gapF, float2(0.05)) / tileScale + 0.5;
    float4 r = texT(g * size);
    float inside = step(0.0, g.x) * step(g.x, 1.0) * step(0.0, g.y) * step(g.y, 1.0);
    return fin(c, r * inside, opacity);
}
